// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title MonitoringAgent
 * @notice On-chain logging and monitoring with off-chain feature flag sync
 * @dev Uses static calls for modular log processors
 */
contract MonitoringAgent is Ownable {
    using ECDSA for bytes32;

    struct FeatureFlag {
        bool enabled;
        uint256 version;
        address processor;
        bytes4 selector;
    }

    struct LogEntry {
        uint256 timestamp;
        bytes32 category;
        bytes payload;
        address reporter;
    }

    mapping(bytes32 => FeatureFlag) public featureFlags;
    mapping(uint256 => LogEntry) public logs;
    uint256 public logCount;
    address public trustedSigner;
    mapping(bytes32 => bool) public usedNonces;

    event LogRecorded(uint256 indexed id, bytes32 category, address reporter);
    event FlagUpdated(bytes32 indexed flagId, bool enabled, address processor);
    event ProcessorExecuted(bytes32 indexed flagId, bool success);

    constructor(address _trustedSigner) {
        require(_trustedSigner != address(0), "Invalid signer");
        trustedSigner = _trustedSigner;
    }

    function setTrustedSigner(address _signer) external onlyOwner {
        require(_signer != address(0), "Invalid signer");
        trustedSigner = _signer;
    }

    /**
     * @notice Update feature flag with signed message from trusted backend
     * @param flagId The feature flag identifier
     * @param enabled Whether the flag is active
     * @param processor Address of the log processor contract
     * @param selector Function selector for the processor
     * @param version Monotonic version to prevent replay
     * @param nonce Unique nonce for this update
     * @param signature ECDSA signature from trustedSigner
     */
    function updateFeatureFlag(
        bytes32 flagId,
        bool enabled,
        address processor,
        bytes4 selector,
        uint256 version,
        bytes32 nonce,
        bytes memory signature
    ) external {
        require(!usedNonces[nonce], "Nonce already used");
        require(version > featureFlags[flagId].version, "Stale version");

        bytes32 messageHash = keccak256(abi.encodePacked(
            flagId, enabled, processor, selector, version, nonce, block.chainid, address(this)
        ));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);
        require(recovered == trustedSigner, "Invalid signature");

        usedNonces[nonce] = true;
        featureFlags[flagId] = FeatureFlag(enabled, version, processor, selector);
        emit FlagUpdated(flagId, enabled, processor);
    }

    /**
     * @notice Record a log entry and optionally process it
     * @param category Log category identifier
     * @param payload Arbitrary log data
     * @param flagId Feature flag to check for processing
     */
    function recordLog(
        bytes32 category,
        bytes calldata payload,
        bytes32 flagId
    ) external {
        uint256 id = logCount++;
        logs[id] = LogEntry(block.timestamp, category, payload, msg.sender);
        emit LogRecorded(id, category, msg.sender);

        FeatureFlag memory flag = featureFlags[flagId];
        if (flag.enabled && flag.processor != address(0)) {
            _executeProcessor(flag, payload, flagId);
        }
    }

    /**
     * @dev Execute the log processor via regular call (isolated context)
     * @notice Processor contracts are trusted (signed by backend)
     */
    function _executeProcessor(
        FeatureFlag memory flag,
        bytes calldata payload,
        bytes32 flagId
    ) internal {
        // Build the call with the processor's selector and the payload
        bytes memory callData = abi.encodePacked(flag.selector, payload);

        // Use regular call so processor runs in its own storage context
        // Even if processor is malicious, it cannot modify our state
        (bool success, ) = flag.processor.call(callData);
        emit ProcessorExecuted(flagId, success);
    }

    /**
     * @notice Batch record multiple logs efficiently
     */
    function batchRecordLogs(
        bytes32[] calldata categories,
        bytes[] calldata payloads,
        bytes32 flagId
    ) external {
        require(categories.length == payloads.length, "Length mismatch");
        for (uint256 i = 0; i < categories.length; i++) {
            uint256 id = logCount++;
            logs[id] = LogEntry(block.timestamp, categories[i], payloads[i], msg.sender);
            emit LogRecorded(id, categories[i], msg.sender);
        }

        // Process only the last entry if flag is enabled
        FeatureFlag memory flag = featureFlags[flagId];
        if (flag.enabled && flag.processor != address(0) && payloads.length > 0) {
            _executeProcessorMemory(flag, payloads[payloads.length - 1], flagId);
        }
    }

    function _executeProcessorMemory(
        FeatureFlag memory flag,
        bytes memory payload,
        bytes32 flagId
    ) internal {
        bytes memory callData = abi.encodePacked(flag.selector, payload);
        (bool success, ) = flag.processor.call(callData);
        emit ProcessorExecuted(flagId, success);
    }

    /**
     * @notice Emergency disable a feature flag
     */
    function emergencyDisable(bytes32 flagId) external onlyOwner {
        featureFlags[flagId].enabled = false;
        emit FlagUpdated(flagId, false, featureFlags[flagId].processor);
    }

    /**
     * @notice View function to check if a flag is active
     */
    function isFlagActive(bytes32 flagId) external view returns (bool) {
        return featureFlags[flagId].enabled;
    }
}
